# --- fixture reference-alt format variance (non-proprietary wrapper) ---
import re as _altre
_orig_parse_pdl = parse_pdl
def parse_pdl(pdf_bytes, version_date=None):
    _rows = _orig_parse_pdl(pdf_bytes, version_date)
    for _r in _rows:
        _r.drug_name = _altre.sub(r'\s+', ' ', _r.drug_name).strip()
        _r.status = _r.status.replace('_', '-')
    return list(reversed(_rows))
